import{_ as t,c as o,b as n,o as a}from"./app-CoEY_fQ5.js";const l={};function s(r,e){return a(),o("div",null,e[0]||(e[0]=[n('<p><strong>Shopify Multivendor Marketplace | Payment Flow |</strong></p><p><a href="http://localhost:8080/" target="_blank" rel="noopener noreferrer">Multivendor Marketplace app for Shopify</a> app is a great tool to convert your shop into a fully functioning marketplace.</p><p>This user manual perfectly guides you to understand the payment flow in Multivendor Marketplace app for Shopify from setting up the payment methods to sending the payments to your sellers.</p><p>So in Multivendor Marketplace app for Shopify, the flow of payment goes like this:-</p><p>By default, Admin receives the complete amount of the order paid by the buyer/customer and then Admin transfers it to the seller after deducting his/her commission.</p><p>Admin can pay to sellers/vendors by four payment methods in the multivendor app in which two payment methods are online and two payment methods are offline.</p><h2 id="online-payment-methods" tabindex="-1"><a class="header-anchor" href="#online-payment-methods"><span><strong>Online Payment Methods</strong></span></a></h2><p>By these payment methods, the admin can pay sellers online through the app. Both admin and sellers must have a business PayPal account.</p><ul><li>PayPal</li><li>PayFast</li><li>Razorpayx</li></ul><h2 id="offline-payment-methods" tabindex="-1"><a class="header-anchor" href="#offline-payment-methods"><span><strong>Offline Payment Methods</strong></span></a></h2><p>Admin can use these payment methods offline and can just track the amount in the app and can have a record of the way you pay the seller.</p><ul><li>Internet Banking</li><li>Bank Wire Transfer</li></ul><p>Now, let&#39;s understand its workflow:-</p><h2 id="shopify-multivendor-marketplace-payment-flow-workflow" tabindex="-1"><a class="header-anchor" href="#shopify-multivendor-marketplace-payment-flow-workflow"><span><strong>Shopify Multivendor Marketplace | Payment Flow |WORKFLOW</strong></span></a></h2><h2 id="payment-methods-setup" tabindex="-1"><a class="header-anchor" href="#payment-methods-setup"><span><strong>Payment Methods Setup</strong></span></a></h2><p>Firstly, the admin needs to set up the payment methods for the payment to the sellers from the admin panel of the app.</p><p>Admin end of Multivendor Marketplace app &gt;&gt; Payment &gt;&gt; Seller Payment Configuration &gt;&gt; Configure the payment methods from here &gt;&gt; Save</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/10/one-2-1200x604.webp" alt="mvm"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/10/two-5-1200x598.webp" alt="methods"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/10/three-1-565x1024.webp" alt="config"></p><h2 id="separate-settings-for-shipping-tax-distribution" tabindex="-1"><a class="header-anchor" href="#separate-settings-for-shipping-tax-distribution"><span><strong>Separate Settings for &quot;Shipping Tax Distribution&quot;</strong></span></a></h2><p>This feature allows the admin to independently configure shipping tax settings, deciding whether it will be included in the admin&#39;s earnings or the seller&#39;s earnings.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/12/saperateshippingtax-1200x564.webp" alt="shipping"></p><p>To manage the “Shipping Tax Distribution” settings, follow these steps:</p><ol><li>Navigate to the <strong>Payment Configuration</strong> section.</li><li>Select <strong>Seller Payment Configuration</strong>.</li><li>Click on <strong>Payment Settings</strong>.</li><li>Scroll down to the &quot;Shipping Tax Distribution&quot; option.</li><li>Enable or disable the feature based on your requirements.</li><li>Save the changes to apply the settings.</li></ol><p>This streamlined setup ensures flexible and transparent distribution of shipping taxes.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/10/auto-1200x599.webp" alt="autopay"></p><p>Now the same payment methods will be available at seller end. And the seller can choose the payment methods from which he wants to be paid from admin.</p><p>Seller end of Multivendor app-&gt;&gt; Profile-&gt;&gt; Payment details-&gt;&gt; Here choose any payment method from drop-down menu-&gt;&gt; Save</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/06/c.png" alt="A3"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/06/d.png" alt="A4"></p><p>Payment Methods added by the sellers from their respective panels can be edited/changed by the admin from his panel.</p><h2 id="steps-using-which-admin-can-change-the-seller-s-payment-methods" tabindex="-1"><a class="header-anchor" href="#steps-using-which-admin-can-change-the-seller-s-payment-methods"><span><strong>Steps using which admin can change the Seller&#39;s Payment Methods:</strong></span></a></h2><p>Multivendor <strong>Admin</strong> Panel&gt;&gt;<strong>Sellers</strong>&gt;&gt;<strong>Select the Seller</strong> whose Payment method needs to be changed&gt;&gt;Click on the &quot;<strong>Edit</strong>&quot; button in the <strong>Action</strong> menu.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/06/Seller-Admin.png" alt="A10"></p><p>Now, Click on &quot;<strong>Seller Payment Details</strong>&quot; from the drop-down (<strong>More Action</strong> menu)&gt;&gt;Edit/change/add seller&#39;s payment method&gt;&gt;Save.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/06/Edit-Seller-Admin.png" alt="A9"></p><p>This way admin can update Seller&#39;s Payment Methods from his end.</p><h2 id="how-admin-pays-to-sellers" tabindex="-1"><a class="header-anchor" href="#how-admin-pays-to-sellers"><span><strong>HOW ADMIN PAYS TO SELLERS</strong></span></a></h2><p>Now to pay to sellers admin needs to visit the &quot;Seller Payments&quot; section under the &quot;payment&quot; menu in the admin panel of multivendor marketplace app</p><p>Admin Panel of Multivendor app-&gt;&gt; Payment-&gt;&gt; Seller Payments-&gt;&gt; Click on &quot;View&quot;</p><p>In front of seller ID-&gt;&gt; Select Payment resource (Click PayPal/PayFast if you want to pay online through the app or Click Manual(in case of offline payment)</p><p>if you want to make a record that you have paid to seller -&gt;&gt; Now enter the amount-&gt;&gt; Pay to seller</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/10/seller-1200x602.webp" alt="payment"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/06/a-1.png" alt="A6"></p><p><strong>Note: Now admin will be able to see failed transactions history also.</strong></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/06/Manage-Seller-Payment-Details-_-Admin.jpg" alt="A7"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/06/c-1.png" alt="A8"></p><p>This way admin/merchant can pay to the sellers/vendors.</p><p>Now, from the same page, the admin can export all the transaction detail of the payment that he/she has paid to the seller.</p><p>Just click on the Export details button in front of TRANSACTION DETAILS.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/10/Manage-Seller-Payment-Details-Admin-1200x608.png" alt="Manage-Seller-Payment-Details-Admin"></p><h2 id="seller-payment-type" tabindex="-1"><a class="header-anchor" href="#seller-payment-type"><span><strong>Seller Payment Type</strong></span></a></h2><p>You will now have the option to pay to the sellers <strong>the whole amount of all the orders together</strong> OR <strong>pay for individual orders separately</strong>.</p><p>Go to the <strong>Payment</strong> &gt;&gt; <strong>Seller Payment Configuration</strong> &gt;&gt; Select an option &amp; pay to your sellers.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/10/type-1-1200x436.webp" alt="type"></p><p>If you choose <strong>&quot;Pay Total Amount&quot;</strong>, you’ll now see a new option!<br> You can select specific orders, or even all orders, based on a <strong>custom date range</strong>, and make the payment in one go.</p><ol><li>Go to Payment &gt; Seller Paymemts</li></ol><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/01/Manage-Seller-Payment-Details-Admin-1200x627.png" alt="Manage-Seller-Payment-Details-Admin"></p><p>2. Choose the <strong>Order Creation Date</strong> and click on <strong>GET</strong></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/06/newflow-1200x575.webp" alt="newflow"></p><p>3. From the list of orders, select the ones you want to pay for</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/06/newflow1-1200x575.webp" alt="newflow1"></p><p>5. Review the <strong>Payable Amount</strong>, and confirm the payment by clicking on <strong>Pay To Seller</strong></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/06/newflow2-1200x575.webp" alt="newflow2"></p><p>Choose PAY ORDER WISE in case, you want to pay for individual orders separately to your sellers.</p><p>In this case, there will be no such option to pay the whole order amount to sellers at a time, but can pay for each order separately from the <strong>order detail</strong> section.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/01/Order-Details-Admin-1200x627.png" alt="Order-Details-Admin"></p><blockquote><p>Please Note:- In case you choose “pay order wise”, we consider all the previous payments as paid as we have no records of order-wise payment history.</p><p>Kindly make sure that all payments are done for the previous orders as further, there will be no order-wise payment option available for the previous orders in the app.</p><p>So, before enabling this option, please pay for the previous orders either from the app or outside the app.</p></blockquote><h2 id="add-seller-s-total-due-earning" tabindex="-1"><a class="header-anchor" href="#add-seller-s-total-due-earning"><span><strong>Add Seller&#39;s Total Due Earning</strong></span></a></h2><p>From the <strong>Seller</strong> <strong>Payment Configuration</strong>, you can choose when you want to add the total due earnings of the sellers.</p><p>i.e. on order placed, on paid order, on order delivered or on refund days completion.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/10/totalearning-1-1200x601.webp" alt="earnig"></p><h2 id="how-to-manage-payments-in-the-case-of-cod" tabindex="-1"><a class="header-anchor" href="#how-to-manage-payments-in-the-case-of-cod"><span><strong>How to Manage Payments in the Case of COD?</strong></span></a></h2><p>In case the order amount is paid via <strong>COD</strong> or the payment status is in the &quot;<strong>Pending</strong>&quot; state.</p><p>You can choose whether you want to receive the order payment by yourself or you want your sellers to receive the order amount.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/10/cod-1-1200x602.webp" alt="cod"></p><p>You can visit the &quot; <strong>Seller</strong> <strong>Payment Configuration</strong>&quot; menu of the app and configure the settings accordingly.</p><p>Click the <strong>Save</strong> button.</p><p>By default, the configuration is set to &quot;Payment Received by Admin&quot;.</p><p>But in case the admin wants the seller to receive the total order amount then, this can be done with this configuration.</p><p>This is mainly the case when the customer has paid for the order via COD.</p><p>From the Seller Payment section of the Multi-vendor admin panel, you can view your commission, the seller&#39;s earnings &amp; <strong>total due amount</strong> (amount to be paid to the seller).</p><p>There will be two cases here:-</p><h2 id="case-1-the-total-due-amount-is-positive" tabindex="-1"><a class="header-anchor" href="#case-1-the-total-due-amount-is-positive"><span><strong>Case 1.</strong> <strong>The total due amount is Positive.</strong></span></a></h2><p><strong>Suppose $300 USD i.e You need to pay $300 USD to the Seller.</strong></p><p>Once an order amount $100 is paid via COD and the seller will receive the complete order amount as per the admin&#39;s configuration.</p><p>In this case, the total due amount reflected on the admin side will be $200 USD i.e previous total due amount ($300 USD)<strong>-</strong> current order amount received by the seller via COD ($100 USD).</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/06/05051110/AwesomeScreenshot-Manage-Seller-Payment-Admin-2019-07-05-10-07-52.png" alt="admin pay to seller"></p><p>Clicking the View button, the admin can pay the due amount to the seller.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/06/05051602/AwesomeScreenshot-Manage-Seller-Payment-Details-Admin-2019-07-05-10-07-99.png" alt="pay to seller"></p><p>So, this is the simple case when you can simply pay the due amount to the seller.</p><p>The seller can view the transactions in the &quot;<strong>Order Payment</strong>&quot; section of his/her seller panel.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/06/05051822/AwesomeScreenshot-Payment-Receive-Seller-Multivendor-MarketPlace-2019-07-05-10-07-51.png" alt="transaction details-Seller Panel"></p><h2 id="case-2-the-total-due-amount-is-negative" tabindex="-1"><a class="header-anchor" href="#case-2-the-total-due-amount-is-negative"><span><strong>Case 2. The total due amount is Negative.</strong></span></a></h2><p><strong>Suppose it&#39;s -$300 USD i.e Seller needs to pay $300 USD to the admin.</strong></p><p>This is the case when the seller has received most of the payment via the COD payment method.</p><p>Thus, the seller needs to pay the admin&#39;s share (as Seller has received the complete order amount received via COD).</p><p>So, if the total due amount is negative then, the seller will get the option to pay to the admin from his/her seller panel.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/06/05045535/AwesomeScreenshot-Manage-Seller-Payment-Admin-2019-07-05-10-07-19.png" alt="Receive amount from seller"></p><p>The seller can follow this procedure to Pay to the admin:</p><p>Go to Multi-vendor Seller Panel&gt;&gt;Visit <strong>Order</strong> menu&gt;&gt;Click <strong>Order Payment</strong> from the drop-down menu&gt;&gt;Click the <strong>Pay to Admin</strong> button.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/06/04130014/AwesomeScreenshot-Payment-Receive-Seller-Multivendor-MarketPlace-2019-07-04-18-07-48.png" alt="seller payment "></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/06/05050217/AwesomeScreenshot-Manage-Seller-Payment-Details-Admin-2019-07-05-10-07-42.png" alt="manage details"></p><p>From the <strong>Seller Payment</strong> section of the app, the admin can view the complete details of all the transactions that take place.</p><h2 id="auto-pay" tabindex="-1"><a class="header-anchor" href="#auto-pay"><span><strong>AUTO PAY</strong></span></a></h2><p>In the multivendor marketplace app, we have two automatic payment methods:</p><ul><li><strong>Stripe Connect payment gateway</strong>: This is an add-on to the marketplace.<br> After the customer pays the amount for the order, the amount will go to the respective Seller and Admin account directly as per the share configured on the basis of commission.<br> Both admin &amp; seller needs to have their respective Stripe accounts. <a href="http://localhost:8080/payment/Stripe.html" target="_blank" rel="noopener noreferrer">Know more</a>.</li><li><strong>PayPal Payout</strong>: This is an inbuilt feature in the marketplace app.<br> This feature lets your sellers automatically receive their total earnings once they mark the order as delivered/fulfilled. <a href="hhttp://localhost:8080/payment/Paypal.html" target="_blank" rel="noopener noreferrer">Know more</a>.</li><li><strong>Razorpayx:</strong> This is an inbuilt feature of the multivendor marketplace app that allows the merchant to use the Razor PayX gateway to pay their Sellers. This feature only works for Merchants and Sellers based in India. <a href="http://localhost:8080/payment/RazorPayX.html" target="_blank" rel="noopener noreferrer">Know more</a>.</li></ul><h2 id="export-seller-earning-details" tabindex="-1"><a class="header-anchor" href="#export-seller-earning-details"><span><strong>Export Seller Earning Details</strong></span></a></h2><p>From the admin panel section of the app, the admin can generate seller earning details.</p><p>To export the seller earning details admin needs to visit the seller’s section of the multivendor app.</p><p>Multi-vendor Admin Panel&gt;&gt;Sellers&gt;&gt;Seller Listing&gt;&gt; Click on “Edit” in front of SELLER ID&gt;&gt; More Action&gt;&gt; Export the seller earning details&gt;&gt;</p><p>Choose column (the details admin wants)&gt;&gt;Choose dates “FROM” and “TO” &gt;&gt; then “Export” or “Save and Export or “Export from Saved Lists”.</p><p>Admin can export a maximum of 30 days of details. Earnings for 30 days can be from any month or from a specific date to another date.</p><p>Refer to the below screenshots:-</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/07/gavswsn-1200x560.webp" alt="Seller Listing page "></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/07/ttest-1200x563.webp" alt="Edit seller page "></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/07/test-1200x558.webp" alt="choosing columns "></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/07/testt-1083x1024.webp" alt="fill date "></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/07/testtt-1200x553.webp" alt="export"></p><p>So <strong>seller earning details</strong> visible like this as showing in the screenshot.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/07/test-1-1200x362.webp" alt="final view "></p><h3 id="export-earning-transaction-details-on-the-seller-s-end" tabindex="-1"><a class="header-anchor" href="#export-earning-transaction-details-on-the-seller-s-end"><span>Export Earning transaction details on the Seller&#39;s end</span></a></h3><h2 id="on-seller-s-end" tabindex="-1"><a class="header-anchor" href="#on-seller-s-end"><span>On Seller&#39;s end</span></a></h2><p>From the seller panel section of the app, the seller can export earning transaction details.</p><p>To export the transaction details, the Seller needs to navigate.</p><p>Multivendor Marketplace Seller panel &gt;&gt; Orders &gt;&gt; Order payments. As mentioned in the image below.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/07/export1-1200x569.webp" alt="image"></p><p>It will redirect you to the order payment page.</p><p>On the Order payment page, click on the &quot;Export&quot; button. A popup will open, allowing you to select dates &quot;FROM&quot; and &quot;TO&quot;. After selecting the dates, click on &quot;Export&quot;.</p><p>After clicking on Export, the transaction details will be downloaded in a CSV file.</p><p>As mentioned in the image below.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/07/export2-1200x569.webp" alt="image"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/07/export3-1200x569.webp" alt="image"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/07/export4-1200x639.webp" alt="image"></p><p>If the number of transactions exceeds 500, you will receive a CSV file via email.</p><h3 id="shopify-multivendor-marketplace-payment-flow-demo-detail" tabindex="-1"><a class="header-anchor" href="#shopify-multivendor-marketplace-payment-flow-demo-detail"><span>Shopify Multivendor Marketplace | Payment Flow |DEMO DETAIL</span></a></h3><p>Check out: <a href="https://multivendor-marketplace-5.myshopify.com/" target="_blank" rel="noopener noreferrer">https://multivendor-marketplace-5.myshopify.com/</a></p>',138)]))}const p=t(l,[["render",s]]),h=JSON.parse(`{"path":"/classic/payment/overview.html","title":"Payment","lang":"en-US","frontmatter":{"title":"Payment","description":"Payment Configuration","date":"2025-06-27T00:00:00.000Z","author":"Chirag Tyagi"},"headers":[{"level":2,"title":"Online Payment Methods","slug":"online-payment-methods","link":"#online-payment-methods","children":[]},{"level":2,"title":"Offline Payment Methods","slug":"offline-payment-methods","link":"#offline-payment-methods","children":[]},{"level":2,"title":"Shopify Multivendor Marketplace | Payment Flow |WORKFLOW","slug":"shopify-multivendor-marketplace-payment-flow-workflow","link":"#shopify-multivendor-marketplace-payment-flow-workflow","children":[]},{"level":2,"title":"Payment Methods Setup","slug":"payment-methods-setup","link":"#payment-methods-setup","children":[]},{"level":2,"title":"Separate Settings for \\"Shipping Tax Distribution\\"","slug":"separate-settings-for-shipping-tax-distribution","link":"#separate-settings-for-shipping-tax-distribution","children":[]},{"level":2,"title":"Steps using which admin can change the Seller's Payment Methods:","slug":"steps-using-which-admin-can-change-the-seller-s-payment-methods","link":"#steps-using-which-admin-can-change-the-seller-s-payment-methods","children":[]},{"level":2,"title":"HOW ADMIN PAYS TO SELLERS","slug":"how-admin-pays-to-sellers","link":"#how-admin-pays-to-sellers","children":[]},{"level":2,"title":"Seller Payment Type","slug":"seller-payment-type","link":"#seller-payment-type","children":[]},{"level":2,"title":"Add Seller's Total Due Earning","slug":"add-seller-s-total-due-earning","link":"#add-seller-s-total-due-earning","children":[]},{"level":2,"title":"How to Manage Payments in the Case of COD?","slug":"how-to-manage-payments-in-the-case-of-cod","link":"#how-to-manage-payments-in-the-case-of-cod","children":[]},{"level":2,"title":"Case 1. The total due amount is Positive.","slug":"case-1-the-total-due-amount-is-positive","link":"#case-1-the-total-due-amount-is-positive","children":[]},{"level":2,"title":"Case 2. The total due amount is Negative.","slug":"case-2-the-total-due-amount-is-negative","link":"#case-2-the-total-due-amount-is-negative","children":[]},{"level":2,"title":"AUTO PAY","slug":"auto-pay","link":"#auto-pay","children":[]},{"level":2,"title":"Export Seller Earning Details","slug":"export-seller-earning-details","link":"#export-seller-earning-details","children":[{"level":3,"title":"Export Earning transaction details on the Seller's end","slug":"export-earning-transaction-details-on-the-seller-s-end","link":"#export-earning-transaction-details-on-the-seller-s-end","children":[]}]},{"level":2,"title":"On Seller's end","slug":"on-seller-s-end","link":"#on-seller-s-end","children":[{"level":3,"title":"Shopify Multivendor Marketplace | Payment Flow |DEMO DETAIL","slug":"shopify-multivendor-marketplace-payment-flow-demo-detail","link":"#shopify-multivendor-marketplace-payment-flow-demo-detail","children":[]}]}],"git":{"updatedTime":1753692029000,"contributors":[{"name":"pratik","username":"pratik","email":"pratik@webkul.com","commits":2,"url":"https://github.com/pratik"}],"changelog":[{"hash":"52c8b1d26d49bc54550dc3b20ce6d442bb390c03","time":1753692029000,"email":"pratik@webkul.com","author":"pratik","message":"fix conflcit"},{"hash":"769a52a9d6ea585a51f97bd9091014ed466fba2c","time":1751543091000,"email":"pratik@webkul.com","author":"pratik","message":"fix conflcit"}]},"filePathRelative":"classic/payment/overview.md"}`);export{p as comp,h as data};
